# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
R=[['拉丁 rapere；第一人称 rapio；分词 raptus','猛地抓住、夺取、带走']]
D=R+[['拉丁 rapidus → 法语 rapide／英语 rapid','有冲劲、迅疾 → 快速的']]
T=R+[['拉丁 raptus → 英语 rapt','被带走 → 心神被吸引、全神贯注']]
U=R+[['中世纪拉丁 raptura → 法语 rapture；另有英语 rapt + -ure 分析','带走、夺取 → 心神被带离平常状态'],['英语 rapture','强烈的喜悦、狂喜']]
N=R+[['拉丁 rapina → 古法语 ravine／raviner／ravinos','掠夺 → 抢食、贪婪的'],['英语 ravenous','饥饿得很厉害；有强烈渴求的']]
S=R+[['拉丁 sub- + rapere → subripere／surripere','从下面、暗中 + 抓走 → 偷偷拿走'],['拉丁 surreptus → surrepticius → 英语 surreptitious','偷偷取走的 → 秘密进行、避人耳目的']]
def H(h,w,m):return h+[[w,m]]
WA=[
E('rapid','/ˈræpɪd/','迅速的；快速发生的；急流〔常用复数 rapids〕','像急水一下卷过去，变化来得快，中间几乎没有拖延。','拉丁 rapere“抓走、带走”形成 rapidus“迅疾的”，经法语 rapide 或直接借入英语。',D,'rapid growth 是迅速增长，rapid change 是快速变化。这个词常形容发展、反应、运动过程；说一个人跑得快，通常用 fast，而不是直接说 a rapid runner。河流中的 rapids 则是水流湍急的一段。','rapid growth；a rapid response；rapid change；river rapids。','quick 常说动作或反应快；rapid 常突出变化、运动持续得很快。二者有重叠，但搭配不完全相同。',('The town has seen rapid growth in recent years.','这座小镇近年来增长很快。'),('The team made a rapid adjustment to the new schedule.','团队迅速适应了新的时间安排。'),sources=['https://www.etymonline.com/word/rapid']),
E('rapidly','/ˈræpɪdli/','迅速地；快速地','把快速放进一个变化过程里：事情正在很快地向前发展。','rapid + -ly，变成说明动作或变化速度的副词。',H(D,'英语 rapid → rapidly','迅速的 → 迅速地'),'rapidly increasing costs 是迅速上涨的成本；change rapidly 是变化很快。它强调变化速度，不自动表示变化是好是坏，也不一定表示突然发生在一瞬间。','grow rapidly；change rapidly；rapidly increasing。','suddenly 强调突然、出乎意料地开始；rapidly 强调整个变化过程很快。',('The water level rose rapidly after the storm.','暴风雨后，水位迅速上升。'),('Her confidence grew rapidly with regular practice.','随着持续练习，她的信心很快增强了。')),
E('rapidity','/rəˈpɪdəti/','迅速；速度快这一特点','让人注意到的不是“发生了”，而是“怎么这么快就发生了”。','来自法语 rapidité 和拉丁 rapiditas，接 rapidus；现代可联系 rapid 与 -ity，历史上名词有独立借入路线。',R+[['拉丁 rapidus → rapiditas → 法语 rapidité','迅疾的 → 迅速这一性质'],['英语 rapidity','运动或变化的迅速程度']],'the rapidity of change 是变化之快；with surprising rapidity 是快得让人惊讶。这个名词比 speed 更书面，常在描述或分析一段变化时使用。物理中的“快度”是专门术语，不能简单当作普通 speed 的别名。','the rapidity of；with great rapidity；astonishing rapidity。','speed 可以是中性的速度量；日常 rapidity 通常突出速度很快，而不是只是有一个速度。',('We were surprised by the rapidity of the recovery.','恢复之快让我们感到意外。'),('The news spread with remarkable rapidity.','消息传播得极快。'),sources=['https://www.etymonline.com/word/rapidity']),
E('rapt','/ræpt/','全神贯注的；听得入迷的','注意力像被眼前的事抓住，周围别的东西暂时退到了背景。','借自拉丁 raptus“被带走的”，是 rapere 的分词；被带走的画面转到心神被吸引。',T,'rapt attention 是听得非常投入；a rapt audience 是被表演牢牢吸引的观众。它通常带强烈兴趣或欣赏，而不是勉强集中注意力。拼写只有四个字母，末尾 /pt/ 都要保留。','rapt attention；a rapt audience；listen in rapt silence。','attentive 只需认真留意；rapt 更像已经被内容迷住。wrapped 是 wrap 的过去式，常与 rapt 同音，但来源和意思不同。',('The children listened to the story with rapt attention.','孩子们全神贯注地听着故事。'),('A rapt audience watched the final scene in silence.','观众看得入迷，静静地看完了最后一幕。'),sources=['https://en.wiktionary.org/wiki/rapt','https://www.etymonline.com/word/rapture']),
E('rapture','英 /ˈræptʃə/；美 /ˈræptʃər/','狂喜；欣喜若狂；特定基督教信仰中的“被提”','快乐强到像把整个人带离了平常状态，一时顾不上周围。','与拉丁 raptus“带走”及中世纪拉丁 raptura 相接；可经法语借入，也有英语 rapt + -ure 的构词分析。',U,'in raptures over something 是喜欢得不得了、兴奋地赞叹。文学中的 rapture 常比普通 happiness 更强烈。大写 the Rapture 在部分基督教末世论中指信徒被带离尘世的事件；那是信仰术语，不是所有基督徒都采用同一种解释。','in raptures；go into raptures over；a feeling of rapture。','joy 可以是一般喜悦；rapture 常是非常强烈、近乎忘我的欣喜。rupture“破裂”拼写很近，却属于另一词族。',('She listened to the final movement in rapture.','她满心陶醉地听着最后一个乐章。'),('The children went into raptures over the surprise visit.','孩子们对这次意外来访兴奋极了。'),sources=['https://www.etymonline.com/word/rapture']),
E('rapturous','/ˈræptʃərəs/','欣喜若狂的；热烈赞赏的','喜悦已经藏不住，直接变成掌声、欢呼或赞美。','rapture 去 e + -ous“充满……的”。',H(U,'英语 rapture → rapturous','狂喜 → 满含狂喜、热烈赞赏的'),'rapturous applause 是极其热烈的掌声；a rapturous reception 是热情到让人感到大家十分欣喜的欢迎。形容评论时，也可以表示赞不绝口。','rapturous applause；a rapturous welcome；rapturous reviews。','warm 是温暖友好的；rapturous 更强烈，带几乎压不住的兴奋与赞赏。',('The singer received rapturous applause at the end of the concert.','音乐会结束时，歌手获得了极其热烈的掌声。'),('The new production opened to rapturous reviews.','新剧一上演，就收到了热情洋溢的好评。')),
E('rapturously','/ˈræptʃərəsli/','欣喜若狂地；极其热情地','把强烈的喜悦直接放到动作里：欢呼、鼓掌、谈论时都满是兴奋。','rapturous + -ly，形容动作所带的热烈喜悦。',H(U,'英语 rapturous → rapturously','热烈欣喜的 → 热烈欣喜地'),'applaud rapturously 是热烈鼓掌；speak rapturously about a performance 是兴奋地赞美表演。它通常比 happily 更有戏剧性，适合描述很强烈的积极反应。','applaud rapturously；cheer rapturously；speak rapturously about。','enthusiastically 是热情地；rapturously 常把兴奋推得更高，带欣喜若狂的感觉。',('The crowd cheered rapturously when the musicians returned.','乐手们返场时，人群兴奋地欢呼起来。'),('He spoke rapturously about the view from the mountain.','他兴奋不已地赞叹山上的景色。'),sources=['https://en.wiktionary.org/wiki/rapturously']),
E('enrapture','英 /ɪnˈræptʃə/；美 /ɪnˈræptʃər/','使陶醉；使欣喜若狂；使着迷','某种声音、景象或故事，把人的注意和情绪整个带走。','en-“使进入某种状态” + rapture“狂喜、陶醉”。',H(U,'英语 en- + rapture → enrapture','使进入狂喜、陶醉的状态'),'音乐可以 enrapture an audience，故事可以 enrapture readers。这个词偏文学或较热烈的赞美，通常不是说轻微觉得不错，而是深深吸引。','enrapture an audience；enrapture readers；be enraptured by。','interest 只需让人感兴趣；enrapture 更像令人忘我地陶醉，情绪强度更高。',('The storyteller’s voice could enrapture an entire room.','讲故事者的声音能让满屋的人听得入迷。'),('The colours of the garden enraptured the visitors.','花园的色彩让游客们陶醉。'),sources=['https://en.wiktionary.org/wiki/enrapture','https://www.merriam-webster.com/thesaurus/enrapture']),
E('enraptured','英 /ɪnˈræptʃəd/；美 /ɪnˈræptʃərd/','陶醉的；被深深迷住的','已经被吸引住了，正沉浸在强烈的欣赏或喜悦中。','enrapture + -d，作过去式、过去分词，也常作形容词。',H(U,'英语 enrapture → enraptured','使陶醉 → 已被迷住、陶醉的'),'be enraptured by a voice 是被声音深深迷住；an enraptured audience 是陶醉其中的观众。这个词把重点放在受到吸引的那一方。','enraptured by；enraptured with；an enraptured listener。','enrapturing 描述让人入迷的事物；enraptured 描述已经入迷的人。',('The audience sat enraptured as the story unfolded.','故事徐徐展开，观众坐在那里听得入迷。'),('She was enraptured by the quiet beauty of the lake.','她陶醉于湖泊宁静的美。'),sources=['https://en.wiktionary.org/wiki/enraptured','https://www.merriam-webster.com/thesaurus/enrapture']),
E('enrapt','/ɪnˈræpt/','出神的；欣喜而入迷的〔文学、较少见〕','整个人沉浸在眼前的内容里，仿佛心神已经被带走。','en- + rapt；与 enraptured 意思相近，但不是把它随意截短后的口语拼写。',H(T,'英语 en- + rapt → enrapt','被吸引住 → 完全沉醉、入迷的'),'enrapt listeners 是听得入神的听众。它的书面、文学色彩较明显；日常通常用 absorbed、fascinated 或 enraptured 更容易被理解。','enrapt attention；enrapt listeners；sit enrapt。','enrapt 与 rapt 都强调入迷；enrapt 通常更少见，不需要理解成一个独立的“超强等级”。',('The listeners sat enrapt through the final song.','听众出神地坐着听完了最后一首歌。'),('He watched the dancers with an enrapt expression.','他神情陶醉地看着舞者们。'),sources=['https://www.merriam-webster.com/dictionary/enrapt','https://en.wiktionary.org/wiki/enrapt']),
E('ravenous','/ˈrævənəs/','饥饿极了的；渴求强烈的','饿得像只想立刻扑向食物，把眼前的东西吃掉。','接古法语 ravinos、ravine 所属的掠夺、抢食词族，远源是拉丁 rapina、rapere；不是鸟名 raven“渡鸦”加后缀。',N,'I’m ravenous 是非常饿；a ravenous appetite 是强烈食欲。也可以形容对知识等事物的强烈渴求，带一种急切地想不断摄取的感觉。','feel ravenous；a ravenous appetite；ravenous for information。','hungry 是一般饿；ravenous 程度更强。与 raven 的鸟名相像只是容易产生联想，不能当作真实词源。',('After the long walk, we were ravenous.','走了很长一段路后，我们饿极了。'),('The students had a ravenous appetite for new ideas.','学生们对新想法充满强烈的求知欲。'),sources=['https://www.etymonline.com/word/ravenous','https://en.wiktionary.org/wiki/ravenous']),
]
